const fs = require('fs');

const readme = fs.readFileSync('README.md', 'utf8');
const headings = readme
  .split('\n')
  .filter((line) => line.startsWith('#'));

fs.writeFileSync('INDEX.md', headings.join('\n') + (headings.length ? '\n' : ''));
console.log(headings.join('\n'));

